-- Idempotentna aktualizacja 12 lekcji Powroźnik. Nie dotyka postępów, kont, uprawnień, płatności ani statusu publikacji.
BEGIN;
insert into public.ta_lessons(course_slug,lesson_no,title_pl,material) values
('powroznik',0,'1. Od włókna do liny: yarn, strand, laid rope','{"module":1,"curriculum_revision":10,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"powroznik-konstrukcja","sections":[{"heading":"Wiedza techniczna","text":"Powróz składa się z włókien, z których skręca się przędze (yarns); przędze tworzą pasma (strands), a kilka pasm jest układanych w linę (laid rope). Lina pleciona (braided) ma inną konstrukcję niż lina skręcana. Różnica wpływa na zachowanie i sposób zakończenia, więc nie wystarczy patrzeć na średnicę."},{"heading":"Proces i ograniczenia","text":"W typowej linie trójpasmowej obciążenie przenoszą współpracujące pasma, a nie pojedyncza zewnętrzna przędza. Sprawdź kolejność produkcji i rozpoznaj widoczną spiralę pasm. Kartę wyrobu uzupełnia się rodzajem włókna, konstrukcją i przeznaczeniem."},{"heading":"Sprawdzalny przykład","text":"Trzy pasma po osiem przędz obejmują łącznie 3×8=24 przędze. Taka liczba nie oznacza 24 odrębnych certyfikowanych elementów ani nie pozwala obliczyć bezpiecznego udźwigu."},{"heading":"Sytuacja zawodowa","text":"Na końcu powrozu rozkręciły się dwie przędze. Przed naprawą trzeba rozpoznać, czy uszkodzone są pojedyncze przędze, całe pasmo czy układ zakończenia."},{"heading":"Praca ucznia","text":"Narysuj cztery poziomy: włókno, przędza, pasmo i lina trójpasmowa. Oznacz, gdzie przebiega skręcanie, oraz porównaj linę plecioną i skręcaną."}],"references":[{"label":"Źródło","url":"https://repository.library.noaa.gov/view/noaa/42456/noaa_42456_DS1.pdf"}],"learning":{"intro":"Powróz składa się z włókien, z których skręca się przędze (yarns); przędze tworzą pasma (strands), a kilka pasm jest układanych w linę (laid rope). Lina pleciona (braided) ma inną konstrukcję niż lina skręcana. Różnica wpływa na zachowanie i sposób zakończenia, więc nie wystarczy patrzeć na średnicę.","situation":"Na końcu powrozu rozkręciły się dwie przędze. Przed naprawą trzeba rozpoznać, czy uszkodzone są pojedyncze przędze, całe pasmo czy układ zakończenia.","task":"Narysuj cztery poziomy: włókno, przędza, pasmo i lina trójpasmowa. Oznacz, gdzie przebiega skręcanie, oraz porównaj linę plecioną i skręcaną.","question":"W jakiej kolejności tworzy się tradycyjną linę skręcaną?","options":["Włókna → przędza → pasma → lina.","Pasmo → lina → pojedyncze włókno → przędza.","Przędza → lina → pasmo → włókno.","Lina → włókno → przędza → pasmo."],"correct":0,"example":"Włókna → przędza → pasma → lina.","explanation":"Włókna tworzą przędze, przędze pasma, a pasma linę.","feedback":["Tak. Włókna tworzą przędze, przędze pasma, a pasma linę.","Nie. Włókna tworzą przędze, przędze pasma, a pasma linę.","Nie. Włókna tworzą przędze, przędze pasma, a pasma linę.","Nie. Włókna tworzą przędze, przędze pasma, a pasma linę."]}}'::jsonb),
('powroznik',1,'2. Konopie, len, sizal i abaka: materiałoznawstwo powroźnika','{"module":1,"curriculum_revision":10,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"powroznik-konstrukcja","sections":[{"heading":"Wiedza techniczna","text":"Konopie i len są roślinami włóknistymi; sizal jest pozyskiwany z agawy, a manila (abaka) z Musa textilis. Różnią się właściwościami włókien, odpornością na wilgoć, zużyciem i technologią przygotowania. Wybór musi odpowiadać środowisku oraz przeznaczeniu, a kolor nie wystarcza do identyfikacji."},{"heading":"Proces i ograniczenia","text":"W historycznej stoczni Charlestown używano konopi i manili. Konopie do niektórych zastosowań pokrywano smołą, natomiast manila była ceniona za naturalną odporność na wodę. Nie można przenosić dawnej impregnacji jako automatycznego sposobu dopuszczenia współczesnej liny do pracy."},{"heading":"Sprawdzalny przykład","text":"Do projektu ogrodowego i ekspozycyjnego można rozważyć różne włókna, ale dla liny przeznaczonej do dźwigania niezbędna jest odpowiednia specyfikacja i udokumentowana wytrzymałość całego wyrobu."},{"heading":"Sytuacja zawodowa","text":"Klient mówi ''chcę naturalną linę do wilgoci''. Zanim zamówisz materiał, ustal ekspozycję na wodę, częstotliwość wymiany, obciążenia i kwalifikację zastosowania."},{"heading":"Praca ucznia","text":"Zbuduj porównanie czterech surowców: pochodzenie, wilgotność, ścieranie, zastosowanie, ograniczenia i sposób weryfikacji danych technicznych."}],"references":[{"label":"Źródło","url":"https://www.nps.gov/places/ropewalk-cny.htm"}],"learning":{"intro":"Konopie i len są roślinami włóknistymi; sizal jest pozyskiwany z agawy, a manila (abaka) z Musa textilis. Różnią się właściwościami włókien, odpornością na wilgoć, zużyciem i technologią przygotowania. Wybór musi odpowiadać środowisku oraz przeznaczeniu, a kolor nie wystarcza do identyfikacji.","situation":"Klient mówi ''chcę naturalną linę do wilgoci''. Zanim zamówisz materiał, ustal ekspozycję na wodę, częstotliwość wymiany, obciążenia i kwalifikację zastosowania.","task":"Zbuduj porównanie czterech surowców: pochodzenie, wilgotność, ścieranie, zastosowanie, ograniczenia i sposób weryfikacji danych technicznych.","question":"Który surowiec powstaje z włókien agawy?","options":["Konopie.","Len.","Sizal.","Manila / abaka."],"correct":2,"example":"Sizal.","explanation":"Sizal pochodzi z agawy; manila/abaka z Musa textilis.","feedback":["Nie. Sizal pochodzi z agawy; manila/abaka z Musa textilis.","Nie. Sizal pochodzi z agawy; manila/abaka z Musa textilis.","Tak. Sizal pochodzi z agawy; manila/abaka z Musa textilis.","Nie. Sizal pochodzi z agawy; manila/abaka z Musa textilis."]}}'::jsonb),
('powroznik',2,'3. Skręt S i Z: jak czytać kierunek spirali','{"module":1,"curriculum_revision":10,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"powroznik-skret","sections":[{"heading":"Wiedza techniczna","text":"Kierunek skrętu rozpoznajemy po ukośnym przebiegu pasm, podobnym do środkowej kreski litery S lub Z. W typowej prawoskrętnej linie trójpasmowej przędze i pasma mogą mieć naprzemienne kierunki, np. przędza Z, pasmo S, lina Z. Konstrukcje specjalne i plecionki mają inne układy."},{"heading":"Proces i ograniczenia","text":"Przeciwne skręty na kolejnych poziomach pomagają utrzymywać zrównoważoną konstrukcję. Sama nazwa Z nie określa wytrzymałości ani dopuszczalnego zastosowania. Normy podają szczegółowe warianty dla lin laid, braided i double braided."},{"heading":"Sprawdzalny przykład","text":"Zwykła lina trójpasmowa Z może składać się z pasm S. Nie należy wnioskować, że wszystkie trzy poziomy mają identyczny kierunek tylko dlatego, że zewnętrzna powierzchnia ma spiralę Z."},{"heading":"Sytuacja zawodowa","text":"Uczeń skręcił pasma i gotową linę w tym samym kierunku, co powoduje rozkręcanie modelu. Przeanalizuj gdzie należy odwrócić skręt, nie tworząc użytkowej liny do obciążeń."},{"heading":"Praca ucznia","text":"Narysuj pięć skoków spirali S i Z i zrób papierowy model przędza Z → pasmo S → lina Z. Porównaj z tekstem normy, bez przykładania obciążenia."}],"references":[{"label":"Źródło","url":"https://www.iteh.asia/catalog/standards/sist/fb952e20-e8de-4d1a-9373-c8917c357c22/sist-en-iso-9554-2019"}],"learning":{"intro":"Kierunek skrętu rozpoznajemy po ukośnym przebiegu pasm, podobnym do środkowej kreski litery S lub Z. W typowej prawoskrętnej linie trójpasmowej przędze i pasma mogą mieć naprzemienne kierunki, np. przędza Z, pasmo S, lina Z. Konstrukcje specjalne i plecionki mają inne układy.","situation":"Uczeń skręcił pasma i gotową linę w tym samym kierunku, co powoduje rozkręcanie modelu. Przeanalizuj gdzie należy odwrócić skręt, nie tworząc użytkowej liny do obciążeń.","task":"Narysuj pięć skoków spirali S i Z i zrób papierowy model przędza Z → pasmo S → lina Z. Porównaj z tekstem normy, bez przykładania obciążenia.","question":"Jaki typowy układ kierunków pasm i gotowej prawoskrętnej liny opisuje standard dla lin laid?","options":["Pasmo Z, gotowa lina Z.","Pasmo S, gotowa lina Z.","Pasmo S, gotowa lina S.","Pasmo Z, gotowa lina bez skrętu."],"correct":1,"example":"Pasmo S, gotowa lina Z.","explanation":"Dla typowej prawoskrętnej liny laid pasma są S, a końcowa lina Z.","feedback":["Nie. Dla typowej prawoskrętnej liny laid pasma są S, a końcowa lina Z.","Tak. Dla typowej prawoskrętnej liny laid pasma są S, a końcowa lina Z.","Nie. Dla typowej prawoskrętnej liny laid pasma są S, a końcowa lina Z.","Nie. Dla typowej prawoskrętnej liny laid pasma są S, a końcowa lina Z."]}}'::jsonb),
('powroznik',3,'4. Ropewalk: długa hala, haki, traveler i top','{"module":1,"curriculum_revision":10,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"powroznik-ropewalk","sections":[{"heading":"Wiedza techniczna","text":"Ropewalk to podłużna przestrzeń produkcyjna dla długich lin. Historyczne urządzenia mogły mieć wirujące haki, mechanizm rozciągający pasma, blok prowadzący zwany top oraz ruchomy traveler utrzymujący naciąg podczas skręcania. To nie jest to samo co niewielkie ręczne szydełko do tkania."},{"heading":"Proces i ograniczenia","text":"W trakcie skręcania zmienia się geometryczna długość pasm, dlatego potrzebny jest kontrolowany przesuw i naciąg. Dla historycznej maszyny nie podawaj uniwersalnych obrotów ani siły naciągu: zależą od włókna, grubości i procesu. Haki, wały i nawijarki wymagają osłon i szkolenia."},{"heading":"Sprawdzalny przykład","text":"Dla zamówienia 12 m gotowej liny nie należy od razu przycinać wszystkich pasm do dokładnie 12 m. Rzeczywista długość początkowa zależy od skrócenia w procesie skrętu, odpadów i sposobu zakończenia."},{"heading":"Sytuacja zawodowa","text":"Praktykant przechodzi przez strefę obracającego się mechanizmu, aby poprawić położenie pasa. Należy przerwać pracę i postępować zgodnie z procedurą zabezpieczenia napędu."},{"heading":"Praca ucznia","text":"Narysuj halę ropewalk z hakami, pasmami, top i traveler. Zaznacz trzy strefy ryzyka pochwycenia, osobę uprawnioną i ruch wózka."}],"references":[{"label":"Źródło","url":"https://www.nps.gov/places/ropewalk-cny.htm"}],"learning":{"intro":"Ropewalk to podłużna przestrzeń produkcyjna dla długich lin. Historyczne urządzenia mogły mieć wirujące haki, mechanizm rozciągający pasma, blok prowadzący zwany top oraz ruchomy traveler utrzymujący naciąg podczas skręcania. To nie jest to samo co niewielkie ręczne szydełko do tkania.","situation":"Praktykant przechodzi przez strefę obracającego się mechanizmu, aby poprawić położenie pasa. Należy przerwać pracę i postępować zgodnie z procedurą zabezpieczenia napędu.","task":"Narysuj halę ropewalk z hakami, pasmami, top i traveler. Zaznacz trzy strefy ryzyka pochwycenia, osobę uprawnioną i ruch wózka.","question":"Dlaczego podczas tworzenia długiej liny ważny jest kontrolowany naciąg oraz przesuw traveler?","options":["Bo skręcanie zmienia geometrię i długość pasm.","Bo każda przędza skraca się zawsze dokładnie o 1%.","Bo traveler służy wyłącznie do podgrzewania włókien.","Bo haki i pasma nie mogą zmieniać położenia podczas produkcji."],"correct":0,"example":"Bo skręcanie zmienia geometrię i długość pasm.","explanation":"Skręt zmienia długość geometryczną pasm i wymaga kontroli naciągu.","feedback":["Tak. Skręt zmienia długość geometryczną pasm i wymaga kontroli naciągu.","Nie. Skręt zmienia długość geometryczną pasm i wymaga kontroli naciągu.","Nie. Skręt zmienia długość geometryczną pasm i wymaga kontroli naciągu.","Nie. Skręt zmienia długość geometryczną pasm i wymaga kontroli naciągu."]}}'::jsonb),
('powroznik',4,'5. Skrócenie podczas skrętu i masa liny — obliczenia','{"module":2,"curriculum_revision":10,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"powroznik-obliczenia","sections":[{"heading":"Materiały i konstrukcja","text":"Przy skręcaniu przędz i pasm ich długość osiowa może się zmienić. W rzetelnym zamówieniu trzeba rozróżnić długość początkową pasma, długość gotowej liny, odpady końcowe i tolerancję wyrobu. Masa liniowa w kg/m opisuje masę na jednostkę długości, nie wytrzymałość."},{"heading":"Metody pomiaru i dokumentacja","text":"W modelowym przykładzie przyjmij hipotetyczne skrócenie o 12%. Aby uzyskać 30 m gotowej liny, potrzebujesz 30/(1−0,12)=34,09 m długości przed skrętem. To parametr szkolny, nie nastawa maszyny. Prawdziwy zapas wynika z doświadczenia i kart procesu."},{"heading":"Przykład obliczeniowy","text":"Dla gotowej liny 30 m o masie liniowej 0,18 kg/m teoretyczna masa wynosi 5,4 kg. Rachunek nie uwzględnia zmian wilgotności ani masy opakowania."},{"heading":"Sytuacja zawodowa","text":"Zamówienie na 30 m liny ma tylko 30 m dostarczonych pasm. Warsztat bez danych o skróceniu i zakończeniach nie powinien gwarantować żądanej długości."},{"heading":"Zadanie ucznia","text":"Oblicz długości przed skręceniem przy 8%, 12% i 15% hipotetycznego skrócenia oraz masę końcowego produktu. Zapisz jednostki, założenia i miejsca kontroli po wyprodukowaniu."}],"references":[{"label":"Źródło techniczne","url":"https://repository.library.noaa.gov/view/noaa/42456/noaa_42456_DS1.pdf"}],"learning":{"intro":"Przy skręcaniu przędz i pasm ich długość osiowa może się zmienić. W rzetelnym zamówieniu trzeba rozróżnić długość początkową pasma, długość gotowej liny, odpady końcowe i tolerancję wyrobu. Masa liniowa w kg/m opisuje masę na jednostkę długości, nie wytrzymałość.","situation":"Zamówienie na 30 m liny ma tylko 30 m dostarczonych pasm. Warsztat bez danych o skróceniu i zakończeniach nie powinien gwarantować żądanej długości.","task":"Oblicz długości przed skręceniem przy 8%, 12% i 15% hipotetycznego skrócenia oraz masę końcowego produktu. Zapisz jednostki, założenia i miejsca kontroli po wyprodukowaniu.","question":"Przy szkolnym skróceniu 12% ile długości początkowej potrzeba dla 30 m gotowej liny?","options":["26,4 m.","31,2 m.","34,09 m.","36,0 m."],"correct":2,"example":"34,09 m.","explanation":"30/0,88≈34,09 m; to jedynie przykład matematyczny.","feedback":["Nie. 30/0,88≈34,09 m; to jedynie przykład matematyczny.","Nie. 30/0,88≈34,09 m; to jedynie przykład matematyczny.","Tak. 30/0,88≈34,09 m; to jedynie przykład matematyczny.","Nie. 30/0,88≈34,09 m; to jedynie przykład matematyczny."]}}'::jsonb),
('powroznik',5,'6. Lina skręcana, pleciona i rdzeniowa — różnice konstrukcji','{"module":2,"curriculum_revision":10,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"powroznik-konstrukcja","sections":[{"heading":"Materiały i konstrukcja","text":"Lina laid składa się ze skręconych pasm. Braided powstaje przez przeplatanie elementów na skos, a double-braid ma zwykle rdzeń i niezależny oplot. Lina o tej samej średnicy może mieć zupełnie inny materiał, masę liniową, wydłużenie i zachowanie przy pracy."},{"heading":"Metody pomiaru i dokumentacja","text":"Przy porównaniu dwóch lin sprawdzaj nie tylko średnicę, ale budowę, materiał, minimalną siłę zrywającą, wydłużenie, dopuszczone środowisko oraz instrukcję zakończeń. Nie można stosować swobodnie splotów i węzłów z liny skręcanej na nowoczesnej linie rdzeniowej."},{"heading":"Przykład obliczeniowy","text":"Dwie liny 10 mm mają inną konstrukcję: jedna to naturalna trójpasmowa, druga syntetyczna z rdzeniem. Nie wynika stąd żadna równość siły zrywającej czy bezpieczeństwa przy podnoszeniu."},{"heading":"Sytuacja zawodowa","text":"Klient prosi o ręcznie skręconą linę do podnoszenia ciężkiego silnika. Takiego zastosowania nie wolno rekomendować bez odpowiedniego udokumentowanego wyrobu i całego systemu podnoszenia."},{"heading":"Zadanie ucznia","text":"Narysuj trzy przekroje: laid 3-strand, braid, core/sheath. Porównaj wymagane dane z kart, ryzyka uszkodzenia i zastosowania, których nie można uzasadnić samym wyglądem."}],"references":[{"label":"Źródło techniczne","url":"https://www.iteh.asia/catalog/standards/sist/fb952e20-e8de-4d1a-9373c8917c22/sist-en-iso-9554-2019"}],"learning":{"intro":"Lina laid składa się ze skręconych pasm. Braided powstaje przez przeplatanie elementów na skos, a double-braid ma zwykle rdzeń i niezależny oplot. Lina o tej samej średnicy może mieć zupełnie inny materiał, masę liniową, wydłużenie i zachowanie przy pracy.","situation":"Klient prosi o ręcznie skręconą linę do podnoszenia ciężkiego silnika. Takiego zastosowania nie wolno rekomendować bez odpowiedniego udokumentowanego wyrobu i całego systemu podnoszenia.","task":"Narysuj trzy przekroje: laid 3-strand, braid, core/sheath. Porównaj wymagane dane z kart, ryzyka uszkodzenia i zastosowania, których nie można uzasadnić samym wyglądem.","question":"Co można wnioskować z tej samej średnicy dwóch lin o innej konstrukcji?","options":["Mają ten sam udźwig.","Mają tę samą rozciągliwość.","Zastępują się we wszystkich zawiesiach.","Nie można przyjąć tej samej wytrzymałości bez danych producenta."],"correct":3,"example":"Nie można przyjąć tej samej wytrzymałości bez danych producenta.","explanation":"Średnica nie wystarcza do określenia wytrzymałości, wydłużenia i dopuszczonego zastosowania.","feedback":["Nie. Średnica nie wystarcza do określenia wytrzymałości, wydłużenia i dopuszczonego zastosowania.","Nie. Średnica nie wystarcza do określenia wytrzymałości, wydłużenia i dopuszczonego zastosowania.","Nie. Średnica nie wystarcza do określenia wytrzymałości, wydłużenia i dopuszczonego zastosowania.","Tak. Średnica nie wystarcza do określenia wytrzymałości, wydłużenia i dopuszczonego zastosowania."]}}'::jsonb),
('powroznik',6,'7. Skok skrętu (lay length) i ocena równomierności','{"module":3,"curriculum_revision":10,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"powroznik-skret","sections":[{"heading":"Materiały i konstrukcja","text":"Skok skrętu, zwany lay length, to długość osiowa, na której pasmo wykonuje pełne okrążenie wokół osi liny. Jest jednym z mierzalnych parametrów konstrukcji. Zbyt nierówny skok może wskazywać na niestabilny proces, ale poprawny skok bez analizy materiału nie dowodzi nośności."},{"heading":"Metody pomiaru i dokumentacja","text":"W przykładowej linie producent deklaruje skok 80 mm, mierzony na całej długości. Na odcinkach A i B odczytano odpowiednio 80 i 96 mm. Różnica względna wynosi (96−80)/80=20%. Czy jest dopuszczalna, określa dokument techniczny, a nie założona uniwersalna norma."},{"heading":"Przykład obliczeniowy","text":"Jeśli wzdłuż 1 m liny rozpoznasz w przybliżeniu 12,5 pełnego obrotu pasma, skok wynosi 1000/12,5=80 mm. Jest to uproszczona interpretacja pomiaru, wymagająca prawidłowego zaznaczenia tego samego pasma."},{"heading":"Sytuacja zawodowa","text":"Uczeń mierzy odległość między dwoma dowolnymi zwojami, bez śledzenia jednego pasma. Otrzymana liczba nie musi być rzeczywistym skokiem."},{"heading":"Zadanie ucznia","text":"Narysuj linę z jednym pasmem oznaczonym kolorem. Odmierz jego pełne okrążenie wzdłuż osi. Policz skok z 1 m i 12,5 obrotów, a następnie zmianę 80→96 mm."}],"references":[{"label":"Źródło techniczne","url":"https://www.exsil.be/en/rope-constructions/cable-laid-twisted/"}],"learning":{"intro":"Skok skrętu, zwany lay length, to długość osiowa, na której pasmo wykonuje pełne okrążenie wokół osi liny. Jest jednym z mierzalnych parametrów konstrukcji. Zbyt nierówny skok może wskazywać na niestabilny proces, ale poprawny skok bez analizy materiału nie dowodzi nośności.","situation":"Uczeń mierzy odległość między dwoma dowolnymi zwojami, bez śledzenia jednego pasma. Otrzymana liczba nie musi być rzeczywistym skokiem.","task":"Narysuj linę z jednym pasmem oznaczonym kolorem. Odmierz jego pełne okrążenie wzdłuż osi. Policz skok z 1 m i 12,5 obrotów, a następnie zmianę 80→96 mm.","question":"Na 1000 mm liny wypada 12,5 pełnego obrotu jednego pasma. Jaki jest średni skok?","options":["12,5 mm.","80 mm.","96 mm.","125 mm."],"correct":1,"example":"80 mm.","explanation":"1000 mm / 12,5≈80 mm na pełny obrót.","feedback":["Nie. 1000 mm / 12,5≈80 mm na pełny obrót.","Tak. 1000 mm / 12,5≈80 mm na pełny obrót.","Nie. 1000 mm / 12,5≈80 mm na pełny obrót.","Nie. 1000 mm / 12,5≈80 mm na pełny obrót."]}}'::jsonb),
('powroznik',7,'8. Uszkodzenia liny: przetarcie, przecięcie, skręt i deformacja','{"module":3,"curriculum_revision":10,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"powroznik-konstrukcja","sections":[{"heading":"Materiały i konstrukcja","text":"Przecięte włókna, miejscowe ścieranie, kinki i hockles, zgniecenie, uszkodzenia chemiczne, starzenie oraz nadmierne wydłużenie to różne kategorie wad. Zewnętrzny wygląd nie zawsze ujawnia całą utratę wytrzymałości. Procedura wycofania zależy od konstrukcji i zastosowania oraz dokumentów producenta."},{"heading":"Metody pomiaru i dokumentacja","text":"Kontrola obejmuje identyfikator, materiał, datę, historię obciążeń, widoczne i niewidoczne podejrzenia uszkodzeń, łączenia i sposób przechowywania. Nie należy deklarować odnowionej wytrzymałości przez owinięcie taśmą ani oceniać szkodliwego przetarcia wyłącznie na podstawie wyglądu końców."},{"heading":"Przykład obliczeniowy","text":"W partii 25 lin weryfikacja wykazała cztery z przeciętym pasmem i dwie z chemicznym przebarwieniem, przy czym jedna lina miała oba objawy. Liczba unikatowych lin z wykrytą wadą wynosi 4+2−1=5, czyli 20% partii."},{"heading":"Sytuacja zawodowa","text":"Ktoś proponuje owinąć uszkodzony środek liny taśmą i ponownie podnosić nią ładunek. Bez oceny i odpowiedniego wyrobu takie działanie jest nieakceptowalne."},{"heading":"Zadanie ucznia","text":"Sporządź tabelę pięciu typów wad ze źródłem, objawem, możliwą niewidoczną szkodą, kryterium wycofania i wymaganym dokumentem. Policz 20% wadliwych sztuk z podanego przykładu."}],"references":[{"label":"Źródło techniczne","url":"https://www.mazzellacompanies.com/solutions/product-warnings/cordage/"}],"learning":{"intro":"Przecięte włókna, miejscowe ścieranie, kinki i hockles, zgniecenie, uszkodzenia chemiczne, starzenie oraz nadmierne wydłużenie to różne kategorie wad. Zewnętrzny wygląd nie zawsze ujawnia całą utratę wytrzymałości. Procedura wycofania zależy od konstrukcji i zastosowania oraz dokumentów producenta.","situation":"Ktoś proponuje owinąć uszkodzony środek liny taśmą i ponownie podnosić nią ładunek. Bez oceny i odpowiedniego wyrobu takie działanie jest nieakceptowalne.","task":"Sporządź tabelę pięciu typów wad ze źródłem, objawem, możliwą niewidoczną szkodą, kryterium wycofania i wymaganym dokumentem. Policz 20% wadliwych sztuk z podanego przykładu.","question":"W 25 linach są cztery z wadą A i dwie z B, ale jedna ma obie. Ile unikatowych lin ma wadę?","options":["6.","5.","4.","3."],"correct":1,"example":"5.","explanation":"Z zasady włączeń i wyłączeń: 4+2−1=5, czyli 20% partii.","feedback":["Nie. Z zasady włączeń i wyłączeń: 4+2−1=5, czyli 20% partii.","Tak. Z zasady włączeń i wyłączeń: 4+2−1=5, czyli 20% partii.","Nie. Z zasady włączeń i wyłączeń: 4+2−1=5, czyli 20% partii.","Nie. Z zasady włączeń i wyłączeń: 4+2−1=5, czyli 20% partii."]}}'::jsonb),
('powroznik',8,'9. Zakończenia: whipping, oczko i splot — różne funkcje','{"module":3,"curriculum_revision":10,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"powroznik-konstrukcja","sections":[{"heading":"Zastosowanie i ograniczenia","text":"Koniec liny skręcanej może się rozkręcać, dlatego stosuje się zabezpieczenia typu whipping/obszycie albo właściwe łączenia. Eye splice (zaplecenie oczka) polega na kontrolowanym przeprowadzeniu pasm zgodnie z konstrukcją, a zwykły węzeł to inna metoda. Nie każde zakończenie jest dozwolone przy określonym obciążeniu i zastosowaniu."},{"heading":"Metoda i dokumentacja","text":"Przy opisie zakończenia rozdziel: materiał, liczbę pasm, kierunek skrętu, zalecaną metodę producenta, sposób oględzin i przeznaczenie. Samo zawiązanie supła lub oklejenie końca nie tworzy certyfikowanego zakończenia do podnoszenia ładunków."},{"heading":"Przykład techniczny","text":"Ktoś zrobił estetyczne oczko na linie, ale dokumentacja zakłada określone sploty wykonane przez fachowca. Brak odpowiedniego potwierdzenia oznacza brak podstaw do deklarowania wytrzymałości zakończenia."},{"heading":"Decyzja zawodowa","text":"Klient chce zastąpić fabryczne zakończenie przypadkowym węzłem w linie przeznaczonej do pracy. Należy odmówić potwierdzenia bezpieczeństwa bez wymaganych danych i kwalifikacji."},{"heading":"Praca końcowa","text":"Narysuj trzy metody: obszyte zakończenie, węzeł, splot oczka. Dla każdej wpisz cel i ograniczenia oraz dokumentację potrzebną w zastosowaniach nośnych."}],"references":[{"label":"Źródło techniczne","url":"https://www.mazzellacompanies.com/solutions/product-warnings/cordage/"}],"learning":{"intro":"Koniec liny skręcanej może się rozkręcać, dlatego stosuje się zabezpieczenia typu whipping/obszycie albo właściwe łączenia. Eye splice (zaplecenie oczka) polega na kontrolowanym przeprowadzeniu pasm zgodnie z konstrukcją, a zwykły węzeł to inna metoda. Nie każde zakończenie jest dozwolone przy określonym obciążeniu i zastosowaniu.","situation":"Klient chce zastąpić fabryczne zakończenie przypadkowym węzłem w linie przeznaczonej do pracy. Należy odmówić potwierdzenia bezpieczeństwa bez wymaganych danych i kwalifikacji.","task":"Narysuj trzy metody: obszyte zakończenie, węzeł, splot oczka. Dla każdej wpisz cel i ograniczenia oraz dokumentację potrzebną w zastosowaniach nośnych.","question":"Dlaczego zwykłe owinięcie końca liny taśmą nie potwierdza możliwości użycia jej jako zawiesia?","options":["Ponieważ taśma zawsze jest mocniejsza od liny.","Ponieważ zakończenie musi odpowiadać konstrukcji, obciążeniu i wymaganiom danego systemu.","Ponieważ liny skręcane nie mogą mieć żadnego zakończenia.","Ponieważ kolor taśmy musi być identyczny z kolorem włókna."],"correct":1,"example":"Ponieważ zakończenie musi odpowiadać konstrukcji, obciążeniu i wymaganiom danego systemu.","explanation":"Wytrzymałość zakończenia wymaga właściwej technologii, kwalifikacji i oceny, nie kosmetycznego owinięcia.","feedback":["Nie. Wytrzymałość zakończenia wymaga właściwej technologii, kwalifikacji i oceny, nie kosmetycznego owinięcia.","Tak. Wytrzymałość zakończenia wymaga właściwej technologii, kwalifikacji i oceny, nie kosmetycznego owinięcia.","Nie. Wytrzymałość zakończenia wymaga właściwej technologii, kwalifikacji i oceny, nie kosmetycznego owinięcia.","Nie. Wytrzymałość zakończenia wymaga właściwej technologii, kwalifikacji i oceny, nie kosmetycznego owinięcia."]}}'::jsonb),
('powroznik',9,'10. Siła zrywająca i obciążenie robocze — nie są tym samym','{"module":4,"curriculum_revision":10,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"powroznik-obliczenia","sections":[{"heading":"Zastosowanie i ograniczenia","text":"Minimalna siła zrywająca (MBL) to parametr określany przez badanie i specyfikację liny, a obciążenie robocze zależy od zastosowania, współczynników bezpieczeństwa, stanu i całego układu połączeń. Nie istnieje jeden uniwersalny współczynnik bezpieczny dla każdego zastosowania."},{"heading":"Metoda i dokumentacja","text":"W przykładzie czysto arytmetycznym lina z MBL=20 kN przy przyjętym przez właściwy system współczynniku 5 miałaby wynik 20/5=4 kN. Nie jest to upoważnienie do stosowania dowolnej liny z MBL=20 kN przy 4 kN obciążenia: trzeba znać przeznaczenie, normy, zakończenia i certyfikację."},{"heading":"Przykład techniczny","text":"Jeżeli założony roboczy model obciążenia wynosi 3 kN przy teoretycznym limicie 4 kN, margines wynosi 1 kN. Nie potwierdza to bezpieczeństwa systemu bez weryfikacji dynamicznych obciążeń i danych producenta."},{"heading":"Decyzja zawodowa","text":"W warsztacie znaleziono ręcznie wykonaną linę bez znanej siły zrywającej. Pracownik chce nią podnieść pojazd. Nie wolno wyznaczyć udźwigu ''na oko'' z liczby pasm."},{"heading":"Praca końcowa","text":"Policz model 20/5=4 kN i porównaj z 3 kN. Wypisz 10 dokumentów lub warunków niezbędnych do rzeczywistej decyzji o dopuszczeniu liny do podnoszenia."}],"references":[{"label":"Źródło techniczne","url":"https://www.dco.uscg.mil/Our-Organization/Assistant-Commandant-for-Prevention-Policy-CG-5P/Traveling-Inspector-Staff-CG-5P-TI/Towing-Vessel-National-Center-of-Expertise/TugSafe/GGTowTermGear/"}],"learning":{"intro":"Minimalna siła zrywająca (MBL) to parametr określany przez badanie i specyfikację liny, a obciążenie robocze zależy od zastosowania, współczynników bezpieczeństwa, stanu i całego układu połączeń. Nie istnieje jeden uniwersalny współczynnik bezpieczny dla każdego zastosowania.","situation":"W warsztacie znaleziono ręcznie wykonaną linę bez znanej siły zrywającej. Pracownik chce nią podnieść pojazd. Nie wolno wyznaczyć udźwigu ''na oko'' z liczby pasm.","task":"Policz model 20/5=4 kN i porównaj z 3 kN. Wypisz 10 dokumentów lub warunków niezbędnych do rzeczywistej decyzji o dopuszczeniu liny do podnoszenia.","question":"Lina ma MBL 20 kN; w zadaniu matematycznym przyjęto dzielnik 5. Jaki jest wynik tego dzielenia?","options":["100 kN.","25 kN.","4 kN.","15 kN."],"correct":2,"example":"4 kN.","explanation":"20/5=4 kN. Liczba nie zastępuje oceny rzeczywistego zastosowania ani certyfikatu.","feedback":["Nie. 20/5=4 kN. Liczba nie zastępuje oceny rzeczywistego zastosowania ani certyfikatu.","Nie. 20/5=4 kN. Liczba nie zastępuje oceny rzeczywistego zastosowania ani certyfikatu.","Tak. 20/5=4 kN. Liczba nie zastępuje oceny rzeczywistego zastosowania ani certyfikatu.","Nie. 20/5=4 kN. Liczba nie zastępuje oceny rzeczywistego zastosowania ani certyfikatu."]}}'::jsonb),
('powroznik',10,'11. Pielęgnacja i przechowywanie: wilgoć, UV, chemia i deformacja','{"module":4,"curriculum_revision":10,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"powroznik-konstrukcja","sections":[{"heading":"Zastosowanie i ograniczenia","text":"Liny naturalne i syntetyczne wymagają różnych warunków magazynowania. Należy chronić je przed nieodpowiednią wilgotnością, wysoką temperaturą, promieniowaniem UV i zanieczyszczeniami niezgodnymi z materiałem. Nadmierne skręty, ostre krawędzie i przeciąganie po szorstkich powierzchniach przyspieszają zużycie."},{"heading":"Metoda i dokumentacja","text":"Dla partii powinno się prowadzić identyfikację, historię użytkowania, terminy przeglądów i kryteria wycofania. Liny bez danych o pochodzeniu i wcześniejszym obciążeniu nie powinny być automatycznie dopuszczane do zadań wymagających potwierdzonej wytrzymałości."},{"heading":"Przykład techniczny","text":"Spośród 40 lin magazynowych 5 ma uszkodzenia mechaniczne, 4 ślady chemii, a 2 należą do obu grup. Unikalnych sztuk z oznakami niezgodności jest 5+4−2=7, czyli 17,5%."},{"heading":"Decyzja zawodowa","text":"Stary powróz znaleziono w wilgotnym magazynie, z nieznanym przebiegiem użytkowania i bez etykiety. Może służyć do ekspozycji historycznej, ale nie można bez badań przywrócić mu statusu sprzętu nośnego."},{"heading":"Praca końcowa","text":"Zbuduj rejestr 40 lin z numerem, materiałem, długością, stanem, warunkami przechowania, historią, datą kontroli i decyzją. Policz udział siedmiu niezgodnych sztuk."}],"references":[{"label":"Źródło techniczne","url":"https://www.mazzellacompanies.com/solutions/product-warnings/cordage/"}],"learning":{"intro":"Liny naturalne i syntetyczne wymagają różnych warunków magazynowania. Należy chronić je przed nieodpowiednią wilgotnością, wysoką temperaturą, promieniowaniem UV i zanieczyszczeniami niezgodnymi z materiałem. Nadmierne skręty, ostre krawędzie i przeciąganie po szorstkich powierzchniach przyspieszają zużycie.","situation":"Stary powróz znaleziono w wilgotnym magazynie, z nieznanym przebiegiem użytkowania i bez etykiety. Może służyć do ekspozycji historycznej, ale nie można bez badań przywrócić mu statusu sprzętu nośnego.","task":"Zbuduj rejestr 40 lin z numerem, materiałem, długością, stanem, warunkami przechowania, historią, datą kontroli i decyzją. Policz udział siedmiu niezgodnych sztuk.","question":"W 40 linach 5 ma wadę mechaniczną, 4 chemiczną, a 2 obie. Ile unikalnych sztuk ma widoczną wadę?","options":["9.","7.","5.","11."],"correct":1,"example":"7.","explanation":"5+4−2=7, czyli 17,5% partii.","feedback":["Nie. 5+4−2=7, czyli 17,5% partii.","Tak. 5+4−2=7, czyli 17,5% partii.","Nie. 5+4−2=7, czyli 17,5% partii.","Nie. 5+4−2=7, czyli 17,5% partii."]}}'::jsonb),
('powroznik',11,'12. Projekt końcowy: lina demonstracyjna z kartą materiałową','{"module":4,"curriculum_revision":10,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"powroznik-obliczenia","sections":[{"heading":"Zastosowanie i ograniczenia","text":"Zadaniem końcowym jest zaprojektowanie modelu ekspozycyjnego trójpasmowej liny z włókien naturalnych. Nie jest to lina dopuszczona do dźwigania ani do asekuracji ludzi. Uczeń ma udokumentować materiał, warstwy konstrukcji, kierunki skrętu, długość, hipotetyczne skrócenie oraz właściwe ograniczenia zastosowania."},{"heading":"Metoda i dokumentacja","text":"Załóż 30 m liny gotowej i szkolne skrócenie 12%: początkowa długość pasm 30/0,88≈34,09 m. Przy masie liniowej 0,18 kg/m gotowa lina waży teoretycznie 5,4 kg. Wymagana jest czytelna etykieta: wyłącznie model edukacyjny, bez dopuszczenia do podnoszenia."},{"heading":"Przykład techniczny","text":"Projekt zawiera trzy pasma, po osiem przędz, czyli 24 przędze łącznie; gotowa lina ma skręt Z, a pasma S. Model ma punkt odniesienia pomiaru lay length i kartę sześciu typowych wad."},{"heading":"Decyzja zawodowa","text":"Klient chce po obejrzeniu demonstracji zastosować model do podnoszenia motocykla. Nie wolno zapewnić go o nośności ani sugerować zastosowania poza zakresem dokumentacji."},{"heading":"Praca końcowa","text":"Oddaj widok liny i przekrój, schemat S/Z, BOM, rachunek długości i masy, kartę sześciu wad oraz dziesięć punktów odbioru. Dodaj wyjaśnienie, dlaczego model demonstracyjny nie może być używany do asekuracji i podnoszenia."}],"references":[{"label":"Źródło techniczne","url":"https://www.nps.gov/places/ropewalk-cny.htm"}],"learning":{"intro":"Zadaniem końcowym jest zaprojektowanie modelu ekspozycyjnego trójpasmowej liny z włókien naturalnych. Nie jest to lina dopuszczona do dźwigania ani do asekuracji ludzi. Uczeń ma udokumentować materiał, warstwy konstrukcji, kierunki skrętu, długość, hipotetyczne skrócenie oraz właściwe ograniczenia zastosowania.","situation":"Klient chce po obejrzeniu demonstracji zastosować model do podnoszenia motocykla. Nie wolno zapewnić go o nośności ani sugerować zastosowania poza zakresem dokumentacji.","task":"Oddaj widok liny i przekrój, schemat S/Z, BOM, rachunek długości i masy, kartę sześciu wad oraz dziesięć punktów odbioru. Dodaj wyjaśnienie, dlaczego model demonstracyjny nie może być używany do asekuracji i podnoszenia.","question":"Dla 30 m liny i masy liniowej 0,18 kg/m jaka jest modelowa masa całej liny?","options":["0,54 kg.","1,8 kg.","18 kg.","5,4 kg."],"correct":3,"example":"5,4 kg.","explanation":"30×0,18=5,4 kg; brak danych o rzeczywistym obciążeniu i certyfikacji.","feedback":["Nie. 30×0,18=5,4 kg; brak danych o rzeczywistym obciążeniu i certyfikacji.","Nie. 30×0,18=5,4 kg; brak danych o rzeczywistym obciążeniu i certyfikacji.","Nie. 30×0,18=5,4 kg; brak danych o rzeczywistym obciążeniu i certyfikacji.","Tak. 30×0,18=5,4 kg; brak danych o rzeczywistym obciążeniu i certyfikacji."]}}'::jsonb)
on conflict(course_slug,lesson_no) do update set
title_pl=excluded.title_pl,material=public.ta_lessons.material||excluded.material,updated_at=now();
update public.ta_courses set description_pl='12 lekcji powroźnictwa: włókno, przędza, pasmo i lina, konopie/len/sizal/manila, skręt S/Z, tradycyjna ropewalk, pomiary długości i skoku, konstrukcje skręcane i plecione, rozpoznawanie uszkodzeń, zakończenia, siła zrywająca i ograniczenia użycia, przechowywanie oraz projekt demonstracyjny. Kurs edukacyjny nie upoważnia do wykonywania lin do dźwigania, zabezpieczenia ludzi ani transportu.' where slug='powroznik';
update public.ta_course_previews set
curiosity='Dlaczego przędza, pasmo i gotowa lina mają naprzemienne kierunki skrętu i co oznaczają litery S oraz Z?',
scenario='Projektujesz ekspozycyjną linę trójpasmową długości 30 m, liczysz hipotetyczne skrócenie, materiał i masę, a następnie oceniasz wady i ograniczenia użytkowania.',
outcome_1='Rozpoznasz rodzaje włókien, strukturę trójpasmowej liny, kierunki skrętu oraz elementy tradycyjnego ropewalk.',
outcome_2='Policzysz długości przed skrętem, masę liniową, skok skrętu oraz różnicę między siłą zrywającą i roboczą.',
outcome_3='Przygotujesz dokumentację modelu liny, ocenę typowych wad i procedurę wycofania z użytkowania, bez nieuprawnionych deklaracji nośności.',
source_url='https://www.nps.gov/places/ropewalk-cny.htm',
module_titles='["I. Materiał, konstrukcja i skręt (1–3)","II. Ropewalk, pomiary i konstrukcje (4–6)","III. Skok skrętu, inspekcja i zakończenia (7–9)","IV. Bezpieczne obciążenia, konserwacja i projekt (10–12)"]'::jsonb,
review_status='review_needed',
editorial_note='12 indywidualnych lekcji technicznych z obliczeniami i kartami kontroli. Do sprawdzenia przez praktyka powroźnictwa oraz specjalistę ds. lin użytkowych. Brak potwierdzonego testu ucznia, egzaminu i deployu Expo. Materiały nie nadają kwalifikacji do używania wyrobów przy podnoszeniu lub asekuracji.',
updated_at=now() where course_slug='powroznik';
COMMIT;
